fun {α} {n m} t f hf =>
  let __Scheme := t.comap f;
  { toScheme := __Scheme, label := fun i => t.label ((t.cellMap f) i), isWellFormed := ⋯, isCoded := ⋯, isLawful := ⋯,
    atStage := ⋯ }

fun {n m} S f =>
  { card := (S.visibleCells f).card, toCellScheme := (S.toCellScheme.comap f).reindex ⇑(S.cellEquiv f),
    rows := S.rows.comap ⋯ }

nodes.docstring:
The scheme whose cells are read through `φ : κ → ι`: the cell `t` has the scope and grade of
`φ t`; ground and faces are unchanged.  Along an equivalence this is a relabelling of cells;
along the inclusion of `D.below X` it is the scheme `D⟨X⟩` of cells below `X`.

nodes.value:
fun {ι} {α} {β} D f =>
  { ground := D.ground.preimage ⇑f ⋯, faces := D.faces.preimage (Finset.map f) ⋯,
    scope := fun d => (D.scope ↑d).preimage ⇑f ⋯, grade := fun d => D.grade ↑d }

