∀ {ι : Type u_2} {κ : Type u_3} {α : Type u_1} {β : Type u_4} {D : VaughtConjecture.CellScheme ι α}
  {E : VaughtConjecture.CellScheme κ β} {φ : κ → ι},
  E.IsLowerEmbedding D φ → ∀ (s : κ) (t : ↑(E.below (E.gradedIndex s))), D.gradedIndex (φ ↑t) ≤ D.gradedIndex (φ s)

∀ {ι : Type u_1} {α : Type u_2} {D : VaughtConjecture.CellScheme ι α} {R : D.Rows} {G C : ι} {P : Set ι}
  {w : ι → VaughtConjecture.Label} {e : ↑(D.below (D.gradedIndex G))} (z : ↑(D.below (D.gradedIndex G))),
  ↑z ∈ P → w ↑z = ⊥ → w ↑e = ⊥ → R.row G e ≤ R.row G z → R.GateReads G C P w e

∀ {ι : Type u_1} {α : Type u_2} {D : VaughtConjecture.CellScheme ι α} {R : D.Rows} {G C : ι} {P : Set ι}
  {w : ι → VaughtConjecture.Label} {e : ↑(D.below (D.gradedIndex G))} (z : ↑(D.below (D.gradedIndex G))),
  ↑z ∈ P → w C ≤ w ↑z → w C ≤ w ↑e → R.row G z ≤ R.row G e → R.GateReads G C P w e
